struct st7789v3_priv {
	struct spi_slave *spi;
	struct gpio_desc gpio_rs_pin;
	struct gpio_desc gpio_rst_pin;
	struct gpio_desc gpio_pwm_pin;
};

static int st7789v3_ofdata_to_platdata(struct udevice *dev)
{
	struct st7789v3_priv *priv = dev_get_priv(dev);

	priv->spi = dev_get_parent_priv(dev);

	return 0;
}

// int spi_xfer(struct spi_slave *slave, unsigned int bitlen, const void *dout, void *din, unsigned long flags)
static int st7789v3_write(struct st7789v3_priv *priv, size_t len, unsigned char *buf )
{
	int ret = 0;
	ret = spi_xfer(priv->spi, len*8, buf, NULL, SPI_XFER_BEGIN | SPI_XFER_END);
	if (ret) {
		printf("Failed to select register %d\n", ret);
		// goto free;
	}
	return ret;
}

static void st7789v3_senddata(struct st7789v3_priv *priv, unsigned char data_buf)
{
	unsigned char buf[1] = {0};
	buf[0] = data_buf;
	// u8 sr_buf[3], wr_buf[3];
	// printf("Enter\n");
	st7789v3_write(priv, 1, buf);
	// printf("Exit\n");
}

static void st7789v3_Write_Index(struct st7789v3_priv *priv, unsigned char cmd)
{
	// printf("Enter\n");
	dm_gpio_set_value(&priv->gpio_rs_pin, 0);
	st7789v3_senddata(priv, cmd);
	dm_gpio_set_value(&priv->gpio_rs_pin, 1);
}

static void st7789v3_Write_Data(struct st7789v3_priv *priv, unsigned char dat)
{
	// printf("Enter\n");
	st7789v3_senddata(priv, dat);
}
/*
panel graphic: 170*320
---------x
-
-
-
Y

*********
*		*
*		*
*		*
*		*
*		*
*********
	  **
	  **
*/
#ifndef DISPLAY_HORIZONTAL
void windows_set(struct st7789v3_priv *priv, unsigned int xs, unsigned int ys, unsigned int xe, unsigned int ye)
{
	// printf("Enter\n");
	st7789v3_Write_Index(priv, 0x2A);
	st7789v3_Write_Data(priv, xs>>8);
	st7789v3_Write_Data(priv, 0x00FF & (xs + 35));
	st7789v3_Write_Data(priv, xe>>8);
	st7789v3_Write_Data(priv, 0x00FF & (xe + 35));

	st7789v3_Write_Index(priv, 0x2B);
	st7789v3_Write_Data(priv, ys >> 8);
	st7789v3_Write_Data(priv, 0x00FF&(ys + 0));
	st7789v3_Write_Data(priv, ye>>8);
	st7789v3_Write_Data(priv, 0x00FF&(ye + 319));

	st7789v3_Write_Index(priv, 0x2C);
}
#else //set lcd display to horizontal mode
void windows_set(struct st7789v3_priv *priv, unsigned int xs, unsigned int ys, unsigned int xe, unsigned int ye)
{
	// printf("Enter\n");
	st7789v3_Write_Index(priv, 0x2A);
	st7789v3_Write_Data(priv, xs>>8);
	st7789v3_Write_Data(priv, 0x00FF & (xs + 0));
	st7789v3_Write_Data(priv, xe>>8);
	st7789v3_Write_Data(priv, 0x00FF & (xe + 319));

	st7789v3_Write_Index(priv, 0x2B);
	st7789v3_Write_Data(priv, ys >> 8);
	st7789v3_Write_Data(priv, 0x00FF&(ys + 35));
	st7789v3_Write_Data(priv, ye>>8);
	st7789v3_Write_Data(priv, 0x00FF&(ye + 35));

	st7789v3_Write_Index(priv, 0x2C);
}
#endif

static void st7789v3_data_init(struct st7789v3_priv *priv)
{
	// int xlen =0, ylen = 0;
	// int value = 0;
	// unsigned char data_buf[2] = {0xff, 0xff}; //red color

	printf("st7789v3_data_init\n");
	// printf("20240907-1055\n");
	dm_gpio_set_value(&priv->gpio_rst_pin,1);
	// dm_gpio_set_value(&priv->gpio_rs_pin,1);
	mdelay(20);
	dm_gpio_set_value(&priv->gpio_rst_pin,0);
	// dm_gpio_set_value(&priv->gpio_rs_pin,0);
	mdelay(20);
	dm_gpio_set_value(&priv->gpio_rst_pin,1);
	// dm_gpio_set_value(&priv->gpio_rs_pin,1);
	mdelay(120);
	st7789v3_Write_Index(priv, 0x11);
	mdelay(120);
	// printf("init data start\n");
	st7789v3_Write_Index(priv, 0xB2);
	st7789v3_Write_Data(priv, 0x0C);
	st7789v3_Write_Data(priv, 0x0C);
	st7789v3_Write_Data(priv, 0x00);
	st7789v3_Write_Data(priv, 0x33);
	st7789v3_Write_Data(priv, 0x33);

	st7789v3_Write_Index(priv, 0x35);
	st7789v3_Write_Data(priv, 0x00);

	st7789v3_Write_Index(priv, 0x36);
#ifndef DISPLAY_HORIZONTAL
	st7789v3_Write_Data(priv, 0x00);
#else
	st7789v3_Write_Data(priv, 0x20|0x40);
#endif

	st7789v3_Write_Index(priv, 0x3A);
	st7789v3_Write_Data(priv, 0x05);

	st7789v3_Write_Index(priv, 0xB7);
	st7789v3_Write_Data(priv, 0x55);

	st7789v3_Write_Index(priv, 0xBB);
	st7789v3_Write_Data(priv, 0x1D);

	st7789v3_Write_Index(priv, 0xC0);
	st7789v3_Write_Data(priv, 0x2C);

	st7789v3_Write_Index(priv, 0xC2);
	st7789v3_Write_Data(priv, 0x01);

	st7789v3_Write_Index(priv, 0xC3);
	st7789v3_Write_Data(priv, 0x13);

	st7789v3_Write_Index(priv, 0xC6);
	st7789v3_Write_Data(priv, 0x0F);

	st7789v3_Write_Index(priv, 0xD0);
	st7789v3_Write_Data(priv, 0xA7);

	st7789v3_Write_Index(priv, 0xD0);
	st7789v3_Write_Data(priv, 0xA4);
	st7789v3_Write_Data(priv, 0xA1);

	st7789v3_Write_Index(priv, 0xE0);
	st7789v3_Write_Data(priv, 0xF0);
	st7789v3_Write_Data(priv, 0x05);
	st7789v3_Write_Data(priv, 0x0D);
	st7789v3_Write_Data(priv, 0x0B);
	st7789v3_Write_Data(priv, 0x0A);
	st7789v3_Write_Data(priv, 0x07);
	st7789v3_Write_Data(priv, 0x31);
	st7789v3_Write_Data(priv, 0x44);
	st7789v3_Write_Data(priv, 0x48);
	st7789v3_Write_Data(priv, 0x37);
	st7789v3_Write_Data(priv, 0x13);
	st7789v3_Write_Data(priv, 0x12);
	st7789v3_Write_Data(priv, 0x2E);
	st7789v3_Write_Data(priv, 0x35);

	st7789v3_Write_Index(priv, 0xE1);
	st7789v3_Write_Data(priv, 0xF0);
	st7789v3_Write_Data(priv, 0x06);
	st7789v3_Write_Data(priv, 0x0A);
	st7789v3_Write_Data(priv, 0x08);
	st7789v3_Write_Data(priv, 0x07);
	st7789v3_Write_Data(priv, 0x23);
	st7789v3_Write_Data(priv, 0x31);
	st7789v3_Write_Data(priv, 0x43);
	st7789v3_Write_Data(priv, 0x47);
	st7789v3_Write_Data(priv, 0x18);
	st7789v3_Write_Data(priv, 0x14);
	st7789v3_Write_Data(priv, 0x14);
	st7789v3_Write_Data(priv, 0x2F);
	st7789v3_Write_Data(priv, 0x36);

	st7789v3_Write_Index(priv, 0x21);
	st7789v3_Write_Index(priv, 0x29);
	printf("st7789v3_data_init ok\n");
#ifndef DISPLAY_HORIZONTAL
	windows_set(priv, 0, 0, 170-1, 320-1);
#else
	windows_set(priv, 0, 0, 320-1, 170-1);
#endif

	st7789v3_write(priv, 108800, gImage_170x320_logo);
	printf("img data ok\n");
}

static int st7789v3_probe(struct udevice *dev)
{
	struct st7789v3_priv *priv = dev_get_priv(dev);
	int ret = 0;

	printf("st7789v3_probe Enter\n");
	ret = spi_claim_bus(priv->spi);
	if (ret) {
		printf("Failed to claim bus: %d\n", ret);
		return ret;
	}

	ret = gpio_request_by_name(dev, "gpio_rst-gpios", 0, &priv->gpio_rst_pin, GPIOD_IS_OUT);
	if (ret) {
		printf("%s: Warning: cannot get enable gpio_rst-gpios: ret=%d\n", __func__, ret);
	}

	ret = gpio_request_by_name(dev, "gpio_rs-gpios", 0, &priv->gpio_rs_pin, GPIOD_IS_OUT);
	if (ret) {
		printf("%s: Warning: cannot get enable gpio_rs-gpios: ret=%d\n", __func__, ret);
	}

	ret = gpio_request_by_name(dev, "gpio_pwm-gpios", 0, &priv->gpio_pwm_pin, GPIOD_IS_OUT);
	if (ret) {
		printf("%s: Warning: cannot get enable gpio_pwm-gpios: ret=%d\n", __func__, ret);
	}

	st7789v3_data_init(priv);

	dm_gpio_set_value(&priv->gpio_pwm_pin, 1);  //enable backlight
	mdelay(5);

	printf("st7789v3_probe Exit\n");
	return 0;
}

static const struct udevice_id st7789v3_ids[] = {
	{ .compatible = "st7789v3" },
	{ }
};

U_BOOT_DRIVER(st7789v3) = {
	.name = "st7789v3",
	.id = UCLASS_ST7789V3_SPI_LCD,
	.of_match = st7789v3_ids,
	.of_to_plat = st7789v3_ofdata_to_platdata,
	.probe = st7789v3_probe,
	.priv_auto = sizeof(struct st7789v3_priv),
};
